1	import { SignJWT, jwtVerify } from "jose";
2	import { cookies } from "next/headers";
3	import { cache } from "react";
4	import { db } from "./db";
5	import type { User } from "@prisma/client";
6	
7	const secret = new TextEncoder().encode(process.env.AUTH_SECRET!);
8	const COOKIE = process.env.NXEON_COOKIE_NAME ?? "nxeon_session";
9	
10	export async function createSession(userId: string) {
11	  const token = await new SignJWT({ sub: userId })
12	    .setProtectedHeader({ alg: "HS256" })
13	    .setIssuedAt()
14	    .setExpirationTime("7d")
15	    .sign(secret);
16	  const jar = await cookies();
17	  jar.set(COOKIE, token, {
18	    httpOnly: true,
19	    sameSite: "lax",
20	    secure: process.env.NODE_ENV === "production" && process.env.COOKIE_SECURE === "1",
21	    maxAge: 60 * 60 * 24 * 7,
22	    path: "/",
23	  });
24	}
25	
26	export async function destroySession() {
27	  const jar = await cookies();
28	  jar.delete(COOKIE);
29	}
30	
31	const IMP_COOKIE = `${process.env.NXEON_COOKIE_NAME ?? "nxeon_session"}_imp`;
32	
33	/** The real signed-in account, ignoring any impersonation. */
34	export const realUser = cache(async (): Promise<User | null> => {
35	  const jar = await cookies();
36	  const token = jar.get(COOKIE)?.value;
37	  if (!token) return null;
38	  try {
39	    const { payload } = await jwtVerify(token, secret);
40	    if (!payload.sub) return null;
41	    const user = await db.user.findUnique({ where: { id: payload.sub } });
42	    if (!user || user.suspended) return null;
43	    return user;
44	  } catch {
45	    return null;
46	  }
47	});
48	
49	/** Effective user: the impersonated customer if an admin is impersonating, else the real user. */
50	export const currentUser = cache(async (): Promise<User | null> => {
51	  const real = await realUser();
52	  if (!real) return null;
53	  if (real.role === "ADMIN") {
54	    const jar = await cookies();
55	    const imp = jar.get(IMP_COOKIE)?.value;
56	    if (imp) {
57	      try {
58	        const { payload } = await jwtVerify(imp, secret);
59	        if (payload.adminId === real.id && typeof payload.sub === "string") {
60	          const target = await db.user.findUnique({ where: { id: payload.sub } });
61	          if (target) return target;
62	        }
63	      } catch {
64	        /* expired/invalid impersonation — fall through to real user */
65	      }
66	    }
67	  }
68	  return real;
69	});
70	
71	/** Non-null when the current request is an admin impersonating a customer. */
72	export const impersonating = cache(async (): Promise<{ admin: User; target: User } | null> => {
73	  const real = await realUser();
74	  if (!real || real.role !== "ADMIN") return null;
75	  const target = await currentUser();
76	  if (!target || target.id === real.id) return null;
77	  return { admin: real, target };
78	});
79	
80	export async function setImpersonation(targetUserId: string) {
81	  const real = await realUser();
82	  if (!real || real.role !== "ADMIN") throw new Error("FORBIDDEN");
83	  const token = await new SignJWT({ sub: targetUserId, adminId: real.id })
84	    .setProtectedHeader({ alg: "HS256" })
85	    .setIssuedAt()
86	    .setExpirationTime("2h")
87	    .sign(secret);
88	  const jar = await cookies();
89	  jar.set(IMP_COOKIE, token, { httpOnly: true, sameSite: "lax", path: "/", maxAge: 7200 });
90	}
91	
92	export async function clearImpersonation() {
93	  const jar = await cookies();
94	  jar.delete(IMP_COOKIE);
95	}
96	
97	export async function requireUser(): Promise<User> {
98	  const user = await currentUser();
99	  if (!user) throw new Error("UNAUTHORIZED");
100	  return user;
101	}
102	
103	export async function requireAdmin(): Promise<User> {
104	  const user = await requireUser();
105	  if (user.role !== "ADMIN") throw new Error("FORBIDDEN");
106	  return user;
107	}
