"use client";

import { useState, useTransition } from "react";
import type { Role } from "@prisma/client";
import { setUserRole } from "@/lib/actions-staff";

const ROLES: Role[] = ["CUSTOMER", "SUPPORT", "BILLING", "ADMIN"];

/**
 * Inline role switcher for the staff manager. Disabled for the acting admin's
 * own row (server also refuses self-demotion). Applies immediately on change.
 */
export function StaffRoleControls({
  userId,
  role,
  isSelf,
}: {
  userId: string;
  role: Role;
  isSelf: boolean;
}) {
  const [pending, start] = useTransition();
  const [value, setValue] = useState<Role>(role);
  const [msg, setMsg] = useState<{ ok?: boolean; error?: string } | null>(null);

  if (isSelf) {
    return <span className="text-xs text-slate-500">You (can&apos;t change own role)</span>;
  }

  return (
    <div className="flex items-center justify-end gap-2">
      <select
        className="input w-32 py-1.5 text-xs"
        value={value}
        disabled={pending}
        onChange={(e) => {
          const next = e.target.value as Role;
          setValue(next);
          setMsg(null);
          start(async () => {
            const res = await setUserRole(userId, next);
            setMsg(res);
            if (res.error) setValue(role);
          });
        }}
      >
        {ROLES.map((r) => (
          <option key={r} value={r}>
            {r.toLowerCase()}
          </option>
        ))}
      </select>
      {pending && <span className="text-xs text-slate-500">saving…</span>}
      {!pending && msg?.ok && <span className="text-xs text-emerald-400">saved</span>}
      {!pending && msg?.error && <span className="text-xs text-red-400">{msg.error}</span>}
    </div>
  );
}

"use client";

import { useState } from "react";

export type EmailTemplate = {
  key: string;
  label: string;
  description: string;
  subject: string;
  sampleArgs: string;
  html: string;
};

/**
 * Left-rail selector + sandboxed live preview of a transactional email.
 * The HTML is rendered inside an isolated iframe (sandbox, no scripts) so the
 * email's inline styles can't leak into the admin panel.
 */
export function EmailTemplatePreview({ templates }: { templates: EmailTemplate[] }) {
  const [active, setActive] = useState(templates[0]?.key ?? "");
  const current = templates.find((t) => t.key === active) ?? templates[0];

  if (!current) return null;

  return (
    <div className="grid gap-5 lg:grid-cols-[240px_1fr]">
      {/* Selector */}
      <div className="card h-fit p-2">
        <div className="space-y-0.5">
          {templates.map((t) => (
            <button
              key={t.key}
              onClick={() => setActive(t.key)}
              className={`nav-item w-full text-left ${t.key === active ? "nav-item-active" : ""}`}
            >
              <span className="truncate">{t.label}</span>
            </button>
          ))}
        </div>
      </div>

      {/* Preview */}
      <div className="space-y-4">
        <div className="card p-5">
          <p className="section-label">Subject line</p>
          <p className="mt-1 text-base font-semibold text-white">{current.subject}</p>
          <p className="mt-3 text-xs text-slate-400">{current.description}</p>
          <div className="mt-3">
            <p className="section-label">Sample data</p>
            <code className="mt-1 block overflow-x-auto rounded-lg bg-black/30 px-3 py-2 font-mono text-xs text-brand-300">
              emails.{current.key}({current.sampleArgs})
            </code>
          </div>
        </div>

        <div className="card overflow-hidden p-0">
          <div className="flex items-center justify-between border-b border-white/[0.06] px-4 py-2.5">
            <p className="text-xs font-medium text-slate-400">Rendered preview</p>
            <p className="text-[11px] text-slate-600">sandboxed · sample data</p>
          </div>
          <iframe
            title={`${current.label} preview`}
            srcDoc={current.html}
            sandbox=""
            className="h-[640px] w-full border-0 bg-white"
          />
        </div>
      </div>
    </div>
  );
}

import { requireArea } from "@/lib/rbac";
import { emails } from "@/lib/mailer";
import { PageHeader, Badge } from "@/components/ui/primitives";
import { EmailTemplatePreview, type EmailTemplate } from "@/components/admin/EmailTemplatePreview";

export const dynamic = "force-dynamic";

export default async function AdminEmailTemplates() {
  await requireArea("platform");

  // Representative sample data so operators see a realistic render of each email.
  const sampleResetLink = "https://revsports.ca/reset?token=SAMPLE-1a2b3c4d";
  const built: EmailTemplate[] = [
    {
      key: "welcome",
      label: "Welcome",
      description: "Sent right after a new customer registers.",
      sampleArgs: '"Alex Rivera"',
      ...emails.welcome("Alex Rivera"),
    },
    {
      key: "provisioned",
      label: "Server provisioned",
      description: "Sent when a VM finishes provisioning and is live, with the SSH command.",
      sampleArgs: '"mc-survival-01", "ssh root@51.79.162.96 -p 20144"',
      ...emails.provisioned("mc-survival-01", "ssh root@51.79.162.96 -p 20144"),
    },
    {
      key: "receipt",
      label: "Payment receipt",
      description: "Sent after a successful wallet top-up or charge.",
      sampleArgs: '"$12.00", "VPS Nebula — 1 month"',
      ...emails.receipt("$12.00", "VPS Nebula — 1 month"),
    },
    {
      key: "renewalWarning",
      label: "Renewal reminder",
      description: "Sent a few days before a server renews, nudging a wallet top-up.",
      sampleArgs: '"mc-survival-01", "August 3, 2026"',
      ...emails.renewalWarning("mc-survival-01", "August 3, 2026"),
    },
    {
      key: "suspended",
      label: "Server suspended",
      description: "Sent when a server is suspended for an overdue balance.",
      sampleArgs: '"mc-survival-01"',
      ...emails.suspended("mc-survival-01"),
    },
    {
      key: "passwordReset",
      label: "Password reset",
      description: "Sent when a customer requests a password reset link (expires in 1 hour).",
      sampleArgs: '"…/reset?token=…"',
      ...emails.passwordReset(sampleResetLink),
    },
  ];

  return (
    <div className="space-y-6">
      <PageHeader
        title="Email templates"
        sub={`${built.length} transactional templates, rendered with sample data`}
      >
        <Badge tone="amber">code-managed</Badge>
      </PageHeader>

      <div className="card p-4">
        <p className="text-sm text-slate-300">
          These are the live transactional emails Nxeon sends to customers. Each preview below is rendered from the
          real template in <code className="rounded bg-black/30 px-1.5 py-0.5 font-mono text-xs text-brand-300">lib/mailer.ts</code>{" "}
          using representative sample data — what you see is exactly what lands in the inbox (minus the logo, which
          loads from your live domain).
        </p>
        <p className="mt-2 text-xs text-slate-500">
          Editing copy is code-side for now: update the <code className="font-mono text-brand-300">emails</code> object
          in <code className="font-mono text-brand-300">lib/mailer.ts</code> and redeploy. Sender/SMTP configuration
          lives under Settings.
        </p>
      </div>

      <EmailTemplatePreview templates={built} />
    </div>
  );
}

"use client";

import { useActionState } from "react";
import { saveGameImage } from "@/lib/actions-games";
import { Badge } from "@/components/ui/primitives";

export type GameImage = {
  id: string;
  name: string;
  family: string;
  version: string;
  minRamMB: number;
  minDiskGB: number;
  active: boolean;
  setupScript: string;
  deployedCount: number;
};

/**
 * Per-image settings form. ADMIN edits RAM/disk minimums, the first-boot setup
 * script, and the active flag (whether the image appears in the deploy wizard).
 */
export function GameImageEditor({ image }: { image: GameImage }) {
  const [state, action, pending] = useActionState(saveGameImage, {} as { ok?: boolean; error?: string });

  return (
    <form action={action} className="card p-5">
      <input type="hidden" name="id" value={image.id} />

      <div className="flex flex-wrap items-start justify-between gap-3">
        <div>
          <div className="flex items-center gap-2">
            <h3 className="text-base font-semibold">{image.name}</h3>
            <Badge tone="brand">{image.family}</Badge>
            {image.version && <span className="text-xs text-slate-500">{image.version}</span>}
          </div>
          <p className="mt-1 text-xs text-slate-500">
            {image.deployedCount} live server{image.deployedCount === 1 ? "" : "s"} using this image
          </p>
        </div>
        <label className="flex items-center gap-2 text-sm">
          <input type="checkbox" name="active" defaultChecked={image.active} />
          Active in deploy wizard
        </label>
      </div>

      <div className="mt-4 grid gap-4 sm:grid-cols-2">
        <div>
          <label className="label">Minimum RAM (MB)</label>
          <input className="input" name="minRamMB" type="number" min={256} step={256} defaultValue={image.minRamMB} required />
        </div>
        <div>
          <label className="label">Minimum disk (GB)</label>
          <input className="input" name="minDiskGB" type="number" min={1} defaultValue={image.minDiskGB} required />
        </div>
      </div>

      <div className="mt-4">
        <label className="label">Setup script (cloud-init runcmd, first boot)</label>
        <textarea
          className="input font-mono text-xs"
          name="setupScript"
          rows={6}
          defaultValue={image.setupScript}
          placeholder="#!/bin/bash&#10;docker run -d --restart unless-stopped ..."
        />
        <p className="mt-1 text-xs text-slate-500">
          Runs once when the VM is first provisioned. Leave blank to inherit the base image default.
        </p>
      </div>

      <div className="mt-4 flex items-center gap-3">
        <button className="btn-primary" disabled={pending}>
          {pending ? "Saving…" : "Save image"}
        </button>
        {state?.ok && !pending && <span className="text-sm text-emerald-400">Saved.</span>}
        {state?.error && !pending && <span className="text-sm text-red-400">{state.error}</span>}
      </div>
    </form>
  );
}
